static int copy_resources(struct task_struct *child)
{
    struct mm_struct *mm;
    int error = -ENOMEM;

    mm = dup_mm(child, current->mm);
    if (!mm)
        return error;

    child->mm = mm;
    child->active_mm = mm;
    return 0;
}

static void queue_new_task(struct task_struct *task)
{
    raw_spin_lock(&task->pi_lock);
    task->__state = TASK_RUNNING;
    enqueue_task(task_rq(task), task, ENQUEUE_WAKEUP);
    raw_spin_unlock(&task->pi_lock);
}

static void *take_free_object(struct kmem_cache *cache)
{
    struct slab *slab = cache->active;
    void *object = slab->freelist;

    if (!object)
        return refill_cpu_cache(cache);

    slab->freelist = get_freepointer(cache, object);
    slab->inuse++;
    return object;
}

static void release_partial_slab(struct slab *slab)
{
    if (slab->inuse == 0)
        discard_slab(slab);
}

static unsigned long slot_for(const dict *table, const void *key)
{
    const uint64_t hash = table->type->hashFunction(key);
    return hash & (table->size - 1);
}

static dictEntry *lookup(dict *table, const void *key)
{
    unsigned long slot = slot_for(table, key);
    for (dictEntry *entry = table->buckets[slot]; entry;
         entry = entry->next) {
        if (table->type->keyCompare(key, entry->key))
            return entry;
    }

    return NULL;
}

static void push_element(client *c, robj *list, robj *value)
{
    quicklist *items = list->ptr;
    int where = c->cmd->proc == lpushCommand
        ? QUICKLIST_HEAD
        : QUICKLIST_TAIL;

    quicklistPush(items, value->ptr, sdslen(value->ptr), where);
    signalModifiedKey(c, c->db, c->argv[1]);
    notifyKeyspaceEvent(NOTIFY_LIST, "push", c->argv[1], c->db->id);
    addReplyLongLong(c, quicklistCount(items));
}

void SceneTree::queue_attach(Node *parent, Node *child) {
    ERR_FAIL_NULL(parent);
    ERR_FAIL_NULL(child);
    pending_nodes.push_back({parent, child});
}

void SceneTree::flush_pending_nodes() {
    for (const PendingNode &item : pending_nodes) {
        if (item.child->get_parent() != nullptr) {
            continue;
        }
        item.parent->add_child(item.child);
        item.child->notification(Node::NOTIFICATION_READY);
    }
    pending_nodes.clear();
}

void CanvasItem::draw_preview(const Rect2 &region, const Color &tint) {
    ERR_FAIL_COND(!is_inside_tree());

    const Transform2D local = get_global_transform();
    const Rect2 bounds = local.xform(region);
    RID canvas = get_canvas_item();

    RenderingServer::get_singleton()->canvas_item_add_rect(
        canvas,
        bounds,
        tint
    );
}

type workQueue struct {
    owner *p
    head  uint32
    tail  uint32
}

func nextRunnable(q *workQueue) *g {
    for {
        head := atomic.LoadAcq(&q.head)
        if head == q.tail {
            return nil
        }
        task := q.owner.runq[head%uint32(len(q.owner.runq))].ptr()
        if atomic.CasRel(&q.head, head, head+1) {
            return task
        }
    }
}

func makeHeader(version uint16, length int) []byte {
    header := make([]byte, 5)
    header[0] = recordTypeHandshake
    header[1] = byte(version >> 8)
    header[2] = byte(version)
    header[3] = byte(length >> 8)
    header[4] = byte(length)
    return header
}

func appendRecord(dst []byte, version uint16, payload []byte) []byte {
    dst = append(dst, makeHeader(version, len(payload))...)
    return append(dst, payload...)
}

func matchingNodes(pod *v1.Pod, nodes []*v1.Node) []*v1.Node {
    eligible := make([]*v1.Node, 0, len(nodes))
    for _, node := range nodes {
        if node.Spec.Unschedulable {
            continue
        }
        nodeLabels := labels.Set(node.Labels)
        selector := labels.SelectorFromSet(pod.Spec.NodeSelector)
        if selector.Matches(nodeLabels) {
            eligible = append(eligible, node)
        }
    }
    return eligible
}

func (c *Controller) reconcile(ctx context.Context, key string) error {
    namespace, name, err := cache.SplitMetaNamespaceKey(key)
    if err != nil {
        return err
    }

    deployment, err := c.lister.Deployments(namespace).Get(name)
    if apierrors.IsNotFound(err) {
        return nil
    }
    if err != nil {
        return err
    }
    return c.ensureReplicaSet(ctx, deployment)
}

fn collect_bindings<'hir>(pattern: &'hir hir::Pat<'hir>) -> Vec<HirId> {
    let mut bindings = Vec::new();

    pattern.walk(|pat| {
        if let hir::PatKind::Binding(_, id, _, _) = pat.kind {
            bindings.push(id);
        }
        true
    });

    bindings.sort_unstable();
    bindings.dedup();
    bindings
}

fn register_type<'tcx>(cx: &mut TypeContext<'tcx>, ty: Ty<'tcx>) -> TypeId {
    if let Some(&id) = cx.ids.get(&ty) {
        return id;
    }
    let id = TypeId::from_usize(cx.types.len());
    cx.types.push(ty);
    cx.ids.insert(ty, id);
    id
}

fn find_type(cx: &TypeContext<'_>, id: TypeId) -> Option<Ty<'_>> {
    cx.types.get(id.index()).copied()
}

def describe_operation(route, schema):
    operation = {
        "summary": route.summary or route.name.replace("_", " "),
        "operationId": route.unique_id,
        "responses": {},
    }

    for status, model in route.response_models.items():
        operation["responses"][str(status)] = {
            "description": "Successful Response",
            "content": {
                "application/json": {"schema": schema(model)},
            },
        }

    return operation

import torch
from torch import Tensor

def normalize_batch(values: Tensor, eps: float = 1e-5) -> Tensor:
    if values.ndim < 2:
        raise ValueError("Expected a batch with a channel dimension")

    reduce = (0, *range(2, values.ndim))
    mean = values.mean(dim=reduce, keepdim=True)
    variance = values.var(dim=reduce, keepdim=True, unbiased=False)
    scale = torch.rsqrt(variance + eps)
    return (values - mean) * scale

def loss(logits: Tensor, targets: Tensor) -> Tensor:
    return torch.nn.functional.cross_entropy(logits, targets)

def backward_nodes(output, gradients):
    if output.grad_fn is None:
        return

    pending = [(output.grad_fn, gradients)]
    while pending:
        node, upstream = pending.pop()
        downstream = node.apply(*upstream)
        for (edge, index), grad in zip(node.next_functions, downstream):
            if edge is not None and grad is not None:
                pending.append((edge, (grad,)))

def rolling_mean(values, window):
    if window <= 0:
        raise ValueError("window must be positive")

    series = Series(values, copy=False)
    valid = series.notna()
    counts = valid.cumsum()
    totals = series.fillna(0).cumsum()

    sums = totals - totals.shift(window, fill_value=0)
    counts = counts - counts.shift(window, fill_value=0)
    return sums.div(counts.where(counts > 0))

const idlePriority = 5;

function scheduleCallback(root, callback, priority) {
  const expiration = priority === idlePriority ? Infinity : now() + 250;
  const task = {root, callback, expiration};
  taskQueue.push(task);
  requestHostCallback(flushWork);
  return task;
}

function flushWork(deadline) {
  while (taskQueue.length && deadline.timeRemaining() > 0) {
    const task = taskQueue.shift();
    const continuation = task.callback();
    if (typeof continuation === 'function') {
      task.callback = continuation;
      taskQueue.unshift(task);
      break;
    }
  }
}

function reconcileChildren(current, workInProgress, nextChildren, lanes) {
  if (current === null) {
    workInProgress.child = mountChildFibers(workInProgress, null, nextChildren, lanes);
    return;
  }

  const previousChildren = current.child;
  workInProgress.child = reconcileChildFibers(
    workInProgress,
    previousChildren,
    nextChildren,
    lanes,
  );
}

interface Edit {
  start: number;
  end: number;
  text: string;
}

function applyEdits(buffer: TextBuffer, edits: readonly Edit[]): void {
  const ordered = [...edits].sort((a, b) => b.start - a.start);
  for (const edit of ordered) {
    const removed = edit.end - edit.start;
    buffer.delete(edit.start, removed);
    if (edit.text.length > 0) {
      buffer.insert(edit.start, edit.text);
    }
  }
}

function resolveCommands(registry: CommandRegistry, prefix: string): QuickPickItem[] {
  const normalized = prefix.trim().toLowerCase();
  const result: QuickPickItem[] = [];

  for (const command of registry.getCommands()) {
    const label = command.title ?? command.id;
    if (!label.toLowerCase().includes(normalized)) {
      continue;
    }
    result.push({ label, description: command.id });
  }

  return result;
}

class StatusBadge extends StatelessWidget {
  const StatusBadge({super.key, required this.label});

  final String label;

  @override
  Widget build(BuildContext context) {
    final colors = Theme.of(context).colorScheme;
    return DecoratedBox(
      decoration: BoxDecoration(
        color: colors.secondaryContainer,
        borderRadius: BorderRadius.circular(12),
      ),
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
        child: Text(label),
      ),
    );
  }
}

class _SelectionState extends State<SelectionList> {
  int _selected = 0;

  @override
  Widget build(BuildContext context) {
    return ListView.builder(
      itemCount: widget.items.length,
      itemBuilder: (context, index) {
        return ListTile(
          title: Text(widget.items[index]),
          selected: index == _selected,
          onTap: () => setState(() => _selected = index),
        );
      },
    );
  }
}
